import json, sqlite3
with open('json/schools.json') as f:
    data = json.load(f)
schools = {r['CDSCode']: r for r in data['records']}
conn = sqlite3.connect('db/satscores.db')
cur = conn.cursor()
cur.execute('SELECT cds, AvgScrRead FROM satscores WHERE AvgScrRead IS NOT NULL')
scores = {row[0]: row[1] for row in cur.fetchall()}
conn.close()
best = None
for cds, sch in schools.items():
    if sch.get('District') == 'Fresno Unified' and cds in scores:
        score = scores[cds]
        if best is None or score < best[0]:
            best = (score, sch)
if best:
    print(best[1].get('Phone'))
else:
    print('Not found')

